"""Dynamic MCP discovery plus handler-path tool authorization."""

from __future__ import annotations

from collections.abc import Callable, Mapping
from contextvars import ContextVar
from dataclasses import dataclass, replace
from functools import partial
from threading import RLock
from typing import Any, ContextManager

from mcp.server.fastmcp import FastMCP
from mcp.server.fastmcp.exceptions import ToolError
from mcp.server.lowlevel import NotificationOptions
from mcp.server.stdio import stdio_server
from mcp.shared.exceptions import UrlElicitationRequiredError
from mcp.types import Icon, ToolAnnotations

from pyocd_debug_mcp.kernel.operations import (
    BoardBusyError,
    ManagedOperation,
    OperationTimeoutError,
    dispatch,
    operation_manager,
    operation_timeout_seconds,
    wrap_layer2_response,
)


@dataclass(frozen=True, slots=True)
class ToolDefinition:
    """Discovery and authorization metadata for one MCP tool."""

    name: str
    hidden_by_default: bool = False
    locked_by_default: bool = False
    prerequisite: str | None = None


class ToolRegistry:
    """Own tool visibility and per-board physical lock state.

    Discovery is deliberately derived from, but weaker than, authorization. A
    hidden tool is still registered with FastMCP so a stale client can call its
    name and receive the same explicit locked-tool refusal.
    """

    def __init__(self) -> None:
        self._definitions: dict[str, ToolDefinition] = {}
        self._unlocked_boards: dict[str, set[str]] = {}
        self._guard = RLock()
        self._list_revision = 0

    @property
    def list_revision(self) -> int:
        with self._guard:
            return self._list_revision

    def register(
        self,
        name: str,
        *,
        hidden: bool = False,
        locked: bool = False,
        prerequisite: str | None = None,
    ) -> ToolDefinition:
        if not name:
            raise ValueError("tool name must not be empty")
        if locked and not prerequisite:
            prerequisite = f"{name}-plan"

        definition = ToolDefinition(
            name=name,
            hidden_by_default=hidden,
            locked_by_default=locked,
            prerequisite=prerequisite,
        )
        with self._guard:
            existing = self._definitions.get(name)
            if existing is not None:
                if existing != definition:
                    raise ValueError(f"tool '{name}' is already registered with different policy")
                return existing
            self._definitions[name] = definition
            self._unlocked_boards[name] = set()
            if not hidden:
                self._list_revision += 1
        return definition

    def configure(
        self,
        name: str,
        *,
        hidden: bool,
        locked: bool,
        prerequisite: str | None = None,
    ) -> ToolDefinition:
        """Set initial policy for an already registered FastMCP tool."""

        if locked and not prerequisite:
            prerequisite = f"{name}-plan"
        with self._guard:
            current = self._require_definition(name)
            was_advertised = self._is_advertised(current)
            updated = replace(
                current,
                hidden_by_default=hidden,
                locked_by_default=locked,
                prerequisite=prerequisite,
            )
            self._definitions[name] = updated
            if not locked:
                self._unlocked_boards[name].clear()
            is_advertised = self._is_advertised(updated)
            if was_advertised != is_advertised:
                self._list_revision += 1
            return updated

    def unregister(self, name: str) -> None:
        with self._guard:
            definition = self._require_definition(name)
            was_advertised = self._is_advertised(definition)
            del self._definitions[name]
            del self._unlocked_boards[name]
            if was_advertised:
                self._list_revision += 1

    def advertised(self) -> tuple[str, ...]:
        with self._guard:
            return tuple(
                name
                for name, definition in self._definitions.items()
                if self._is_advertised(definition)
            )

    def definition(self, name: str) -> ToolDefinition:
        with self._guard:
            return self._require_definition(name)

    def is_registered(self, name: str) -> bool:
        """Return whether policy metadata exists without raising for an optional alias."""

        with self._guard:
            return name in self._definitions

    def unlock(self, name: str, board_id: str) -> None:
        if not board_id:
            raise ValueError("board_id must not be empty")
        with self._guard:
            definition = self._require_definition(name)
            if not definition.locked_by_default:
                return
            was_advertised = self._is_advertised(definition)
            self._unlocked_boards[name].add(board_id)
            if was_advertised != self._is_advertised(definition):
                self._list_revision += 1

    def relock(self, name: str, board_id: str) -> None:
        with self._guard:
            definition = self._require_definition(name)
            was_advertised = self._is_advertised(definition)
            self._unlocked_boards[name].discard(board_id)
            if was_advertised != self._is_advertised(definition):
                self._list_revision += 1

    def reset(self) -> None:
        """Restore every guarded tool to its default run-start lock state."""

        with self._guard:
            before = self.advertised()
            for boards in self._unlocked_boards.values():
                boards.clear()
            if before != self.advertised():
                self._list_revision += 1

    def is_unlocked(self, name: str, board_id: str | None) -> bool:
        with self._guard:
            definition = self._require_definition(name)
            if not definition.locked_by_default:
                return True
            return board_id is not None and board_id in self._unlocked_boards[name]

    def require_unlocked(self, name: str, board_id: str | None) -> None:
        if self.is_unlocked(name, board_id):
            return
        definition = self.definition(name)
        prerequisite = definition.prerequisite or f"{name}-plan"
        board_text = f" for board '{board_id}'" if board_id else ""
        raise ToolError(
            f"Tool '{name}' is locked{board_text}. Call '{prerequisite}' first."
        )

    def _require_definition(self, name: str) -> ToolDefinition:
        try:
            return self._definitions[name]
        except KeyError as exc:
            raise ToolError(f"Unknown tool: {name}") from exc

    def _is_advertised(self, definition: ToolDefinition) -> bool:
        return not definition.hidden_by_default or bool(self._unlocked_boards[definition.name])


TimeoutResolver = Callable[[str, Mapping[str, object] | None], float]
InvocationGuard = Callable[[str, str, Mapping[str, object]], None]
ExecutionLockResolver = Callable[[str], ContextManager[object]]
OperationResourceBinder = Callable[[ManagedOperation], None]
OperationFinalizerResolver = Callable[[str, str, Mapping[str, object]], Callable[[], None] | None]


@dataclass(frozen=True, slots=True)
class GuardedDispatchPolicy:
    guard: InvocationGuard
    lock_for_board: ExecutionLockResolver


class RegistryFastMCP(FastMCP):
    """FastMCP adapter with dynamic discovery, locks, and bounded dispatch."""

    def __init__(
        self,
        name: str | None = None,
        *,
        registry: ToolRegistry | None = None,
        timeout_resolver: TimeoutResolver = operation_timeout_seconds,
        **settings: Any,
    ) -> None:
        self.registry = registry or ToolRegistry()
        self._timeout_resolver = timeout_resolver
        self._guarded_dispatch: dict[str, GuardedDispatchPolicy] = {}
        self._layer2_tools: set[str] = set()
        self._operation_resource_binder: OperationResourceBinder | None = None
        self._finalizer_resolver: OperationFinalizerResolver | None = None
        self._dispatch_revision: ContextVar[int | None] = ContextVar(
            f"registry_dispatch_revision_{id(self)}", default=None
        )
        super().__init__(name=name, **settings)

    def configure_operation_resources(self, binder: OperationResourceBinder) -> None:
        """Bind persistent board resources into each managed hardware invocation."""

        self._operation_resource_binder = binder

    def configure_finalizers(self, resolver: OperationFinalizerResolver) -> None:
        """Configure strict resolution of structured on-exit actions."""

        self._finalizer_resolver = resolver

    def configure_layer2(self, name: str) -> None:
        """Mark a registered hardware action for common failure wrapping."""

        self.registry.definition(name)
        self._layer2_tools.add(name)

    def configure_guarded_dispatch(
        self,
        name: str,
        *,
        guard: InvocationGuard,
        lock_for_board: ExecutionLockResolver,
    ) -> None:
        """Bind one registered synchronous tool to plan enforcement and its board lock."""

        self.registry.definition(name)
        self._guarded_dispatch[name] = GuardedDispatchPolicy(guard, lock_for_board)

    def add_tool(
        self,
        fn: Callable[..., Any],
        name: str | None = None,
        title: str | None = None,
        description: str | None = None,
        annotations: ToolAnnotations | None = None,
        icons: list[Icon] | None = None,
        meta: dict[str, Any] | None = None,
        structured_output: bool | None = None,
    ) -> None:
        super().add_tool(
            fn,
            name=name,
            title=title,
            description=description,
            annotations=annotations,
            icons=icons,
            meta=meta,
            structured_output=structured_output,
        )
        tool_name = name or fn.__name__
        tool = self._tool_manager.get_tool(tool_name)
        if tool is None:
            raise RuntimeError(f"Tool registration failed: {tool_name}")
        argument_model = tool.fn_metadata.arg_model
        argument_model.model_config["extra"] = "forbid"
        argument_model.model_rebuild(force=True)
        tool.parameters = argument_model.model_json_schema(by_alias=True)
        self.registry.register(tool_name)

    def remove_tool(self, name: str) -> None:
        super().remove_tool(name)
        self.registry.unregister(name)

    async def list_tools(self):  # type: ignore[no-untyped-def]
        tools = await super().list_tools()
        advertised = frozenset(self.registry.advertised())
        return [tool for tool in tools if tool.name in advertised]

    async def call_tool(self, name: str, arguments: dict[str, Any]):  # type: ignore[no-untyped-def]
        revision_before = self._dispatch_revision.get()
        dispatch_token = None
        if revision_before is None:
            revision_before = self.registry.list_revision
            dispatch_token = self._dispatch_revision.set(revision_before)
        try:
            board_value = arguments.get("board_id")
            board_id = board_value if isinstance(board_value, str) and board_value else None
            try:
                self.registry.require_unlocked(name, board_id)
            except ToolError as exc:
                if name in self._layer2_tools:
                    raise ToolError(wrap_layer2_response(str(exc))) from exc
                raise
            tool = self._tool_manager.get_tool(name)
            if tool is None:
                raise ToolError(f"Unknown tool: {name}")
            validated_arguments = self._validated_arguments(tool, arguments)
            dispatch_policy = self._guarded_dispatch.get(name)
            before_execution = None
            execution_lock = None
            if dispatch_policy is not None:
                if board_id is None:
                    raise ToolError(f"Guarded tool '{name}' requires a non-empty board_id.")
                before_execution = partial(
                    dispatch_policy.guard,
                    name,
                    board_id,
                    dict(arguments),
                )
                execution_lock = dispatch_policy.lock_for_board(board_id)
            context = self.get_context()
            timeout = self._timeout_resolver(name, arguments)
            finalizer = None
            if arguments.get("on_exit") is not None:
                if board_id is None or self._finalizer_resolver is None:
                    raise ToolError(f"Tool '{name}' cannot accept an on_exit finalizer.")
                try:
                    finalizer = self._finalizer_resolver(name, board_id, arguments)
                except ValueError as exc:
                    raise ToolError(str(exc)) from exc
            try:
                request_id = context.request_id
            except ValueError:
                request_id = None

            if tool.is_async:

                async def invoke_async():  # type: ignore[no-untyped-def]
                    return await self._invoke_validated_async(
                        tool, validated_arguments, context
                    )

                return await dispatch(
                    name,
                    board_id,
                    invoke_async,
                    timeout,
                    before_execution=before_execution,
                    execution_lock=execution_lock,
                    request_id=request_id,
                    serialize_board=name != "action_batch",
                    resource_binder=self._operation_resource_binder
                    if name in self._layer2_tools
                    else None,
                    finalizer=finalizer,
                )

            def invoke_sync():  # type: ignore[no-untyped-def]
                return self._invoke_validated_sync(tool, validated_arguments, context)

            return await dispatch(
                name,
                board_id,
                invoke_sync,
                timeout,
                before_execution=before_execution,
                execution_lock=execution_lock,
                request_id=request_id,
                resource_binder=self._operation_resource_binder
                if name in self._layer2_tools
                else None,
                finalizer=finalizer,
            )
        except (OperationTimeoutError, BoardBusyError) as exc:
            message = str(exc)
            if name in self._layer2_tools:
                message = wrap_layer2_response(message)
            raise ToolError(message) from exc
        except ToolError as exc:
            if name in self._layer2_tools:
                raise ToolError(wrap_layer2_response(str(exc))) from exc
            raise
        except Exception as exc:
            if name in self._layer2_tools:
                raise ToolError(wrap_layer2_response(str(exc))) from exc
            raise
        finally:
            if dispatch_token is not None:
                try:
                    if self.registry.list_revision != revision_before:
                        await self._send_tool_list_changed()
                finally:
                    self._dispatch_revision.reset(dispatch_token)

    @staticmethod
    def _validated_arguments(tool: Any, arguments: dict[str, Any]) -> dict[str, Any]:
        """Apply FastMCP's ordinary input parsing once before guarded dispatch."""

        try:
            parsed = tool.fn_metadata.pre_parse_json(arguments)
            return tool.fn_metadata.arg_model.model_validate(parsed).model_dump_one_level()
        except Exception as exc:
            raise ToolError(f"Error executing tool {tool.name}: {exc}") from exc

    @staticmethod
    async def _invoke_validated_async(
        tool: Any, arguments: dict[str, Any], context: Any
    ) -> Any:
        try:
            invocation_arguments = dict(arguments)
            if tool.context_kwarg is not None:
                invocation_arguments[tool.context_kwarg] = context
            result = await tool.fn(**invocation_arguments)
            return tool.fn_metadata.convert_result(result)
        except UrlElicitationRequiredError:
            raise
        except Exception as exc:
            raise ToolError(f"Error executing tool {tool.name}: {exc}") from exc

    @staticmethod
    def _invoke_validated_sync(tool: Any, arguments: dict[str, Any], context: Any) -> Any:
        try:
            invocation_arguments = dict(arguments)
            if tool.context_kwarg is not None:
                invocation_arguments[tool.context_kwarg] = context
            result = tool.fn(**invocation_arguments)
            return tool.fn_metadata.convert_result(result)
        except UrlElicitationRequiredError:
            raise
        except Exception as exc:
            raise ToolError(f"Error executing tool {tool.name}: {exc}") from exc

    def create_initialization_options(self):  # type: ignore[no-untyped-def]
        """Advertise the tool-list notification capability to MCP clients."""

        return self._mcp_server.create_initialization_options(
            NotificationOptions(tools_changed=True)
        )

    async def _send_tool_list_changed(self) -> None:
        context = self.get_context()
        try:
            session = context.session
        except ValueError:
            return
        await session.send_tool_list_changed()

    async def run_stdio_async(self) -> None:
        """Run stdio while advertising dynamic tool-list notifications."""

        try:
            async with stdio_server() as (read_stream, write_stream):
                await self._mcp_server.run(
                    read_stream,
                    write_stream,
                    self.create_initialization_options(),
                )
        finally:
            operation_manager.cancel_all("stdio client EOF or server shutdown")

"""Adversarial registered-boundary checks for H01 batch strictness."""

from __future__ import annotations

import json
import unittest
from types import SimpleNamespace
from typing import ClassVar

import anyio
from mcp.client.session import ClientSession
from mcp.server.fastmcp.exceptions import ToolError
from pydantic import BaseModel, field_validator

from pyocd_debug_mcp.kernel.operations import SAFE_EXIT_REMINDER
from pyocd_debug_mcp.kernel.registry import RegistryFastMCP, ToolRegistry
from pyocd_debug_mcp.tools.batch import BatchChild, build_batch_handlers


class _CountingPayload(BaseModel):
    """Records Pydantic validation without making handler execution observable by accident."""

    validations: ClassVar[int] = 0
    value: int

    @field_validator("value")
    @classmethod
    def _count_validation(cls, value: int) -> int:
        cls.validations += 1
        return value


class _NotificationSession:
    def __init__(self) -> None:
        self.calls = 0

    async def send_tool_list_changed(self) -> None:
        self.calls += 1


class H01StrictMcpBoundaryTests(unittest.IsolatedAsyncioTestCase):
    """Prove H01 semantics at the registered FastMCP boundary, without hardware."""

    def _mcp(self) -> tuple[RegistryFastMCP, ToolRegistry, _NotificationSession]:
        registry = ToolRegistry()
        mcp = RegistryFastMCP("h01-strict-boundary", registry=registry, timeout_resolver=lambda *_: 1)
        session = _NotificationSession()
        # The production call path obtains its context from a live MCP request.  This is the
        # smallest faithful host-only stand-in needed to observe its notification side effect.
        mcp.get_context = lambda: SimpleNamespace(request_id="h01", session=session)  # type: ignore[method-assign]
        return mcp, registry, session

    @staticmethod
    def _body(error: ToolError) -> dict[str, object]:
        text = str(error)
        body, reminder = text.rsplit("\n", 1)
        if reminder != SAFE_EXIT_REMINDER:
            raise AssertionError(f"missing or duplicated safe-exit reminder: {text!r}")
        start = body.find("{")
        if start < 0:
            raise AssertionError(f"missing structured batch payload: {text!r}")
        payload, end = json.JSONDecoder().raw_decode(body[start:])
        if body[start + end :]:
            raise AssertionError(f"multiple or trailing batch payloads: {text!r}")
        return payload

    @staticmethod
    def _text(result: object) -> str:
        """Read FastMCP's converted text through sync or async dispatch wrapping."""

        if isinstance(result, tuple):
            result = result[0]
        while isinstance(result, list):
            if len(result) != 1:
                raise AssertionError(f"expected exactly one converted result, got {result!r}")
            result = result[0]
        return result.text  # type: ignore[union-attr]

    async def test_cl001_all_registered_root_schemas_are_strict_and_valid_calls_keep_defaults(self) -> None:
        mcp, _, _ = self._mcp()
        calls: list[object] = []

        def zero() -> str:
            calls.append("zero")
            return "zero"

        def typed(value: int = 7) -> str:
            calls.append(value)
            return str(value)

        mcp.add_tool(zero)
        mcp.add_tool(typed)
        for name, arguments in (("zero", {"unexpected": True}), ("typed", {"unexpected": True})):
            with self.subTest(tool=name):
                tool = mcp._tool_manager.get_tool(name)  # type: ignore[reportPrivateUsage]
                self.assertIsNotNone(tool)
                self.assertIs(tool.parameters["additionalProperties"], False)  # type: ignore[union-attr]
                with self.assertRaisesRegex(ToolError, "unexpected"):
                    await tool.run(arguments, convert_result=True)  # type: ignore[union-attr]
        self.assertEqual(calls, [])

        result = await mcp.call_tool("typed", {})
        self.assertEqual(self._text(result), "7")
        self.assertEqual(calls, [7])

    async def test_cl002_lock_precedes_schema_then_validation_precedes_guard_and_handler_once(self) -> None:
        mcp, registry, _ = self._mcp()
        guard_calls: list[dict[str, object]] = []
        handler_calls: list[int] = []

        def guarded(board_id: str, payload: _CountingPayload) -> str:
            del board_id
            handler_calls.append(payload.value)
            return "ok"

        mcp.add_tool(guarded)
        registry.configure("guarded", hidden=True, locked=True, prerequisite="guarded-plan")
        mcp.configure_guarded_dispatch(
            "guarded",
            guard=lambda _name, _board, fields: guard_calls.append(dict(fields)),
            lock_for_board=lambda _board: _NullLock(),
        )

        _CountingPayload.validations = 0
        with self.assertRaisesRegex(ToolError, "guarded-plan"):
            await mcp.call_tool(
                "guarded", {"board_id": "board", "payload": {"value": 1}, "unexpected": True}
            )
        self.assertEqual((_CountingPayload.validations, guard_calls, handler_calls), (0, [], []))

        registry.unlock("guarded", "board")
        with self.assertRaisesRegex(ToolError, "unexpected"):
            await mcp.call_tool(
                "guarded", {"board_id": "board", "payload": {"value": 2}, "unexpected": True}
            )
        self.assertEqual(guard_calls, [])
        self.assertEqual(handler_calls, [])
        self.assertEqual(_CountingPayload.validations, 1)

        await mcp.call_tool("guarded", {"board_id": "board", "payload": {"value": 3}})
        self.assertEqual(_CountingPayload.validations, 2)
        self.assertEqual(guard_calls, [{"board_id": "board", "payload": {"value": 3}}])
        self.assertEqual(handler_calls, [3])

    async def test_cl001_cl003_batch_schema_and_child_refusal_are_strict_structured_errors(self) -> None:
        mcp, _, _ = self._mcp()
        child_calls: list[str] = []

        async def child(board_id: str, payload: _CountingPayload) -> str:
            child_calls.append(f"{board_id}:{payload.value}")
            return "ok"

        mcp.add_tool(child)
        batch = build_batch_handlers(mcp.call_tool, tool_exists=mcp.registry.is_registered)["action_batch"]
        mcp.add_tool(batch, name="action_batch")
        batch_tool = mcp._tool_manager.get_tool("action_batch")  # type: ignore[reportPrivateUsage]
        self.assertIsNotNone(batch_tool)
        self.assertIs(batch_tool.parameters["additionalProperties"], False)  # type: ignore[union-attr]
        self.assertIs(batch_tool.parameters["$defs"]["BatchChild"]["additionalProperties"], False)  # type: ignore[index,union-attr]

        for arguments in (
            {"board_id": "board", "actions": [], "outer_extra": True},
            {
                "board_id": "board",
                "actions": [{"tool_name": "child", "arguments": {"board_id": "board"}, "envelope_extra": True}],
            },
        ):
            with self.subTest(arguments=arguments):
                with self.assertRaisesRegex(ToolError, "extra"):
                    await mcp.call_tool("action_batch", arguments)
        self.assertEqual(child_calls, [])

        _CountingPayload.validations = 0
        with self.assertRaises(ToolError) as raised:
            await mcp.call_tool(
                "action_batch",
                {
                    "board_id": "board",
                    "actions": [
                        {
                            "tool_name": "child",
                            "arguments": {
                                "board_id": "board",
                                "payload": {"value": 9},
                                "child_extra": True,
                            },
                        }
                    ],
                },
            )
        payload = self._body(raised.exception)
        self.assertEqual(payload["status"], "batch_failed")
        self.assertEqual(payload["completed"], [])
        failure = payload["failure"]
        self.assertIsInstance(failure, dict)
        self.assertEqual(failure["index"], 0)
        self.assertEqual(failure["tool_name"], "child")
        self.assertIn("child_extra", failure["message"])
        self.assertEqual(child_calls, [])
        self.assertEqual(_CountingPayload.validations, 1)

    async def test_cl002_cl003_valid_batch_validates_each_child_once_and_stops_on_first_failure(self) -> None:
        mcp, _, _ = self._mcp()
        seen: list[str] = []

        async def child(board_id: str, payload: _CountingPayload) -> str:
            seen.append(f"{board_id}:{payload.value}")
            if payload.value == 2:
                raise ToolError("child refusal")
            return str(payload.value)

        mcp.add_tool(child)
        mcp.add_tool(
            build_batch_handlers(mcp.call_tool, tool_exists=mcp.registry.is_registered)["action_batch"],
            name="action_batch",
        )
        _CountingPayload.validations = 0
        result = await mcp.call_tool(
            "action_batch",
            {"board_id": "board", "actions": [{"tool_name": "child", "arguments": {"board_id": "board", "payload": {"value": 1}}}]},
        )
        self.assertIn('"status":"batch_completed"', self._text(result))
        self.assertEqual((_CountingPayload.validations, seen), (1, ["board:1"]))

        with self.assertRaises(ToolError) as raised:
            await mcp.call_tool(
                "action_batch",
                {
                    "board_id": "board",
                    "actions": [
                        {"tool_name": "child", "arguments": {"board_id": "board", "payload": {"value": 1}}},
                        {"tool_name": "child", "arguments": {"board_id": "board", "payload": {"value": 2}}},
                        {"tool_name": "child", "arguments": {"board_id": "board", "payload": {"value": 3}}},
                    ],
                },
            )
        payload = self._body(raised.exception)
        self.assertEqual(payload["status"], "batch_failed")
        self.assertEqual([item["index"] for item in payload["completed"]], [0])
        self.assertEqual(payload["failure"]["index"], 1)  # type: ignore[index]
        self.assertEqual(seen, ["board:1", "board:1", "board:2"])

    async def test_cl004_nested_revision_notification_is_coalesced_and_state_is_restored(self) -> None:
        mcp, registry, session = self._mcp()

        async def child(board_id: str) -> str:
            registry.relock("child", board_id)
            return "done"

        async def failing(board_id: str) -> str:
            del board_id
            raise ToolError("inner refusal")

        mcp.add_tool(child)
        mcp.add_tool(failing)
        registry.configure("child", hidden=True, locked=True, prerequisite="child-plan")
        mcp.add_tool(
            build_batch_handlers(mcp.call_tool, tool_exists=registry.is_registered)["action_batch"],
            name="action_batch",
        )

        registry.unlock("child", "board")
        await mcp.call_tool("child", {"board_id": "board"})
        self.assertEqual(session.calls, 1)

        registry.unlock("child", "board")
        await mcp.call_tool(
            "action_batch",
            {"board_id": "board", "actions": [{"tool_name": "child", "arguments": {"board_id": "board"}}]},
        )
        self.assertEqual(session.calls, 2, "one outer batch request must yield one notification")

        with self.assertRaises(ToolError):
            await mcp.call_tool(
                "action_batch",
                {"board_id": "board", "actions": [{"tool_name": "failing", "arguments": {"board_id": "board"}}]},
            )
        registry.unlock("child", "board")
        await mcp.call_tool("child", {"board_id": "board"})
        self.assertEqual(session.calls, 3, "an inner failure must not leak nesting state")

    async def test_cl003_wire_results_mark_refusals_as_errors_without_losing_batch_payload(self) -> None:
        """Use MCP's request handler, rather than treating a ToolError as a wire result."""

        mcp = RegistryFastMCP("h01-wire", timeout_resolver=lambda *_: 1)
        child_calls: list[str] = []

        async def child(board_id: str, value: int) -> str:
            child_calls.append(f"{board_id}:{value}")
            if value == 2:
                raise ToolError("child refusal")
            return str(value)

        mcp.add_tool(child)
        mcp.add_tool(
            build_batch_handlers(mcp.call_tool, tool_exists=mcp.registry.is_registered)["action_batch"],
            name="action_batch",
        )
        client_send, server_receive = anyio.create_memory_object_stream()
        server_send, client_receive = anyio.create_memory_object_stream()
        async with anyio.create_task_group() as tasks:
            tasks.start_soon(
                mcp._mcp_server.run,  # type: ignore[reportPrivateUsage]
                server_receive,
                server_send,
                mcp.create_initialization_options(),
            )
            async with ClientSession(client_receive, client_send) as client:
                await client.initialize()
                for arguments in (
                    {"board_id": "board", "actions": [], "outer_extra": True},
                    {
                        "board_id": "board",
                        "actions": [
                            {
                                "tool_name": "child",
                                "arguments": {"board_id": "board", "value": 1},
                                "envelope_extra": True,
                            }
                        ],
                    },
                    {
                        "board_id": "board",
                        "actions": [
                            {
                                "tool_name": "child",
                                "arguments": {
                                    "board_id": "board",
                                    "value": 1,
                                    "child_extra": True,
                                },
                            }
                        ],
                    },
                ):
                    with self.subTest(arguments=arguments):
                        refusal = await client.call_tool("action_batch", arguments)
                        self.assertTrue(refusal.isError)
                failed = await client.call_tool(
                    "action_batch",
                    {
                        "board_id": "board",
                        "actions": [
                            {"tool_name": "child", "arguments": {"board_id": "board", "value": 1}},
                            {"tool_name": "child", "arguments": {"board_id": "board", "value": 2}},
                        ],
                    },
                )
                self.assertTrue(failed.isError)
                failed_text = failed.content[0].text
                self.assertIn('"status":"batch_failed"', failed_text)
                self.assertIn('"index":1', failed_text)
                self.assertEqual(failed_text.count(SAFE_EXIT_REMINDER), 1)

                completed = await client.call_tool(
                    "action_batch",
                    {
                        "board_id": "board",
                        "actions": [
                            {"tool_name": "child", "arguments": {"board_id": "board", "value": 3}}
                        ],
                    },
                )
                self.assertFalse(completed.isError)
                self.assertIn('"status":"batch_completed"', completed.content[0].text)
            tasks.cancel_scope.cancel()
        self.assertEqual(child_calls, ["board:1", "board:2", "board:3"])


